return [{
  json: {
    openrouter_model: 'openai/gpt-4o-mini',
    searxng_base_url: 'http://searxng:8080',
    max_tool_steps: 8,
    enhance_model: 'google/gemini-2.5-flash-image',
    judge_model: 'openai/gpt-4o-mini',
    enhance_max_attempts: 2
  }
}];

const cfg = $('Config').first().json;
const item = $input.item.json;
const product = { brand: item.brand, name: item.product_name, category: item.category };

const MODEL = cfg.openrouter_model;
const SEARXNG_URL = `${cfg.searxng_base_url}/search`;
const MAX_STEPS = cfg.max_tool_steps;

function resolveUrl(url, base) {
  if (!url) return null;
  url = String(url).trim();
  if (/^https?:\/\//i.test(url)) return url;
  const schemeMatch = String(base).match(/^([a-zA-Z][a-zA-Z0-9+.-]*:)/);
  const scheme = schemeMatch ? schemeMatch[1] : 'https:';
  if (/^\/\//.test(url)) return scheme + url;
  const originMatch = String(base).match(/^[a-zA-Z][a-zA-Z0-9+.-]*:\/\/[^/]+/);
  const origin = originMatch ? originMatch[0] : '';
  if (url.startsWith('/')) return origin + url;
  const basePath = String(base).replace(/^[a-zA-Z][a-zA-Z0-9+.-]*:\/\/[^/]+/, '').replace(/[^/]*$/, '');
  return origin + basePath + url;
}

async function searchImages(query) {
  const res = await this.helpers.httpRequest({
    method: 'GET',
    url: SEARXNG_URL,
    qs: { q: query, format: 'json', categories: 'images' },
    json: true
  });
  return ((res && res.results) || []).slice(0, 8).map(r => ({
    page_url: r.url, image_url: r.img_src, title: r.title, source: r.engine
  }));
}

async function searchWeb(query) {
  const res = await this.helpers.httpRequest({
    method: 'GET',
    url: SEARXNG_URL,
    qs: { q: query, format: 'json', categories: 'general' },
    json: true
  });
  return ((res && res.results) || []).slice(0, 8).map(r => ({ url: r.url, title: r.title, snippet: r.content }));
}

async function fetchPage(pageUrl) {
  let html;
  try {
    html = await this.helpers.httpRequest({
      method: 'GET',
      url: pageUrl,
      headers: { 'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36' }
    });
  } catch (e) {
    return { page_url: pageUrl, error: e.message, images: [] };
  }
  const htmlStr = String(html);
  const found = [];
  const metaTags = htmlStr.match(/<meta\b[^>]*>/gi) || [];
  for (const tag of metaTags) {
    const propMatch = tag.match(/(?:property|name)\s*=\s*["']([^"']+)["']/i);
    const contentMatch = tag.match(/content\s*=\s*["']([^"']+)["']/i);
    if (!propMatch || !contentMatch) continue;
    const prop = propMatch[1].toLowerCase();
    if (['og:image', 'og:image:secure_url', 'twitter:image', 'twitter:image:src'].includes(prop)) {
      const resolved = resolveUrl(contentMatch[1], pageUrl);
      if (resolved) found.push({ url: resolved, tag: prop });
    }
  }
  const titleMatch = htmlStr.match(/<title[^>]*>([^<]+)<\/title>/i);
  return { page_url: pageUrl, title: titleMatch ? titleMatch[1].trim() : null, images: found.slice(0, 5) };
}

const tools = [
  { type: 'function', function: { name: 'search_images', description: 'Search the web for images matching a query. Returns candidate image URLs with the page they came from.', parameters: { type: 'object', properties: { query: { type: 'string' } }, required: ['query'] } } },
  { type: 'function', function: { name: 'search_web', description: 'General web search (not image-specific). Use to find the manufacturer/retailer product page.', parameters: { type: 'object', properties: { query: { type: 'string' } }, required: ['query'] } } },
  { type: 'function', function: { name: 'fetch_page', description: 'Fetch a page and extract its title plus og:image/twitter:image meta tags. Use to verify a product page and pull its real photo.', parameters: { type: 'object', properties: { url: { type: 'string' } }, required: ['url'] } } },
  { type: 'function', function: { name: 'select_images', description: 'Final answer: up to 3 distinct real photos of this exact product (different angles or listings), ranked best first.', parameters: { type: 'object', properties: { images: { type: 'array', minItems: 1, maxItems: 3, items: { type: 'object', properties: { image_url: { type: 'string' }, source_page_url: { type: 'string' }, credit: { type: 'string', description: 'e.g. "Sony (manufacturer)" or "Best Buy product listing"' }, reason: { type: 'string', description: 'Why this photo is confirmed to be the real product, not a lookalike or unrelated result.' } }, required: ['image_url', 'reason'] } } }, required: ['images'] } } }
];

async function runTool(name, args) {
  if (name === 'search_images') return searchImages.call(this, args.query);
  if (name === 'search_web') return searchWeb.call(this, args.query);
  if (name === 'fetch_page') return fetchPage.call(this, args.url);
  throw new Error('unknown tool ' + name);
}

async function verifyImageUrl(url) {
  try {
    const res = await this.helpers.httpRequest({
      method: 'GET',
      url,
      headers: { Range: 'bytes=0-2048' },
      returnFullResponse: true,
      encoding: 'arraybuffer'
    });
    const ct = (res.headers['content-type'] || res.headers['Content-Type'] || '').toString();
    return res.statusCode < 400 && ct.startsWith('image/');
  } catch (e) { return false; }
}

async function callOpenRouter(messages, forceSelect) {
  const body = {
    model: MODEL,
    messages,
    tools,
    tool_choice: forceSelect ? { type: 'function', function: { name: 'select_images' } } : 'auto'
  };
  const res = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://openrouter.ai/api/v1/chat/completions',
    headers: { Authorization: `Bearer ${$env.OPENROUTER_API_KEY}`, 'Content-Type': 'application/json' },
    body,
    json: true
  });
  return res.choices[0].message;
}

const messages = [
  {
    role: 'system',
    content: `You are a product-photo research agent for an affiliate review website. Given a product (brand, name, category), find up to 3 DISTINCT real, accurate photos of that exact product (different angles, colorways, or listings - not the same image twice) using the tools available (search_images, search_web, fetch_page). Prefer official manufacturer or major retailer photos over random stock/wiki images. It is fine to return fewer than 3 if you cannot confirm more.

Be careful of false matches: a brand name can collide with unrelated things (e.g. "Sony" also makes cameras, "Anker" is also a historical person's surname) - verify each image/page is actually about THIS product before selecting it. Avoid logos, placeholder icons, and unrelated lifestyle photos.

CRITICAL: you may ONLY select an image_url that was literally returned to you in a search_images or fetch_page tool result during this conversation. Never invent or recall a URL from memory - if you haven't seen it in a tool result this session, it doesn't count as found.

You have a limited number of tool calls. Use search_images and/or search_web to gather multiple candidates, then fetch_page on the most promising ones to confirm before calling select_images with your final ranked list.`
  },
  { role: 'user', content: `Find up to 3 real product photos for: ${product.brand} ${product.name} (category: ${product.category}).` }
];

const toolTrace = [];
const groundedUrls = new Set();
function ground(urls) { for (const u of urls) if (u) groundedUrls.add(u); }
let finalImages = null;

for (let step = 0; step < MAX_STEPS && !finalImages; step++) {
  const forceSelect = step === MAX_STEPS - 1;
  const msg = await callOpenRouter.call(this, messages, forceSelect);
  messages.push(msg);

  if (!msg.tool_calls || msg.tool_calls.length === 0) {
    toolTrace.push({ step, type: 'assistant_text', content: msg.content });
    continue;
  }

  for (const tc of msg.tool_calls) {
    const args = JSON.parse(tc.function.arguments || '{}');
    if (tc.function.name === 'select_images') {
      const candidates = (args.images || []).filter(i => i && i.image_url).slice(0, 3);
      const grounded = candidates.filter(c => groundedUrls.has(c.image_url));
      const ungrounded = candidates.filter(c => !groundedUrls.has(c.image_url));
      if (!grounded.length) {
        // Nothing survived grounding - push back and let the agent search again rather
        // than silently accepting a URL it never actually saw in a tool result.
        toolTrace.push({ step, tool: 'select_images', args, rejected: 'ungrounded', ungrounded });
        messages.push({ role: 'tool', tool_call_id: tc.id, content: JSON.stringify({ error: 'None of those image_urls appeared in a prior tool result. Search again and only select URLs you actually saw in a tool result.' }) });
        break;
      }
      const verified = [];
      for (const c of grounded) {
        const ok = await verifyImageUrl.call(this, c.image_url);
        if (ok) verified.push(c);
      }
      finalImages = verified;
      toolTrace.push({ step, tool: 'select_images', args, grounded: grounded.length, ungrounded: ungrounded.length, live_verified: verified.length });
      break;
    }
    let result;
    try { result = await runTool.call(this, tc.function.name, args); }
    catch (e) { result = { error: e.message }; }
    if (Array.isArray(result)) ground(result.map(r => r.image_url).filter(Boolean));
    else if (result && result.images) ground(result.images.map(im => im.url).filter(Boolean));
    toolTrace.push({ step, tool: tc.function.name, args, result });
    messages.push({ role: 'tool', tool_call_id: tc.id, content: JSON.stringify(result) });
  }
}

const photos = finalImages || [];
const primary = photos[0] || null;

return [{
  json: {
    ...item,
    image_url: primary ? primary.image_url : null,
    image_credit: primary ? primary.credit : null,
    source_page_url: primary ? primary.source_page_url : null,
    selection_reason: primary ? primary.reason : null,
    image_source: primary ? 'agentic_openrouter' : 'none',
    gallery_image_urls: photos.slice(1).map(p => ({ url: p.image_url, credit: p.credit })),
    photos,
    tool_trace: toolTrace
  }
}];

const cfg = $('Config').first().json;
const item = $input.item.json;

const EDIT_MODEL = cfg.enhance_model;
const JUDGE_MODEL = cfg.judge_model;
const MAX_ATTEMPTS = cfg.enhance_max_attempts;

async function toDataUrl(url) {
  const res = await this.helpers.httpRequest({
    method: 'GET',
    url,
    returnFullResponse: true,
    encoding: 'arraybuffer'
  });
  const mime = (res.headers['content-type'] || res.headers['Content-Type'] || 'image/jpeg').toString();
  const buf = Buffer.isBuffer(res.body) ? res.body : Buffer.from(res.body);
  return `data:${mime};base64,${buf.toString('base64')}`;
}

async function editImage(dataUrl, product, feedback) {
  const prompt = `Enhance this product photo for a review website: increase sharpness/clarity, correct exposure and color balance, reduce compression artifacts and noise. Keep the actual product (${product}), its shape, colors, and any text/branding on the product itself completely unchanged - only improve overall image quality. Do not add, remove, or alter any object in the scene.${feedback ? ' Previous attempt feedback: ' + feedback : ''}`;
  const res = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://openrouter.ai/api/v1/chat/completions',
    headers: { Authorization: `Bearer ${$env.OPENROUTER_API_KEY}`, 'Content-Type': 'application/json' },
    body: {
      model: EDIT_MODEL,
      messages: [{ role: 'user', content: [{ type: 'text', text: prompt }, { type: 'image_url', image_url: { url: dataUrl } }] }]
    },
    json: true
  });
  const msg = res.choices[0].message;
  return (msg.images && msg.images.length) ? msg.images[0].image_url.url : null;
}

async function judgeImage(originalDataUrl, editedDataUrl, product) {
  const res = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://openrouter.ai/api/v1/chat/completions',
    headers: { Authorization: `Bearer ${$env.OPENROUTER_API_KEY}`, 'Content-Type': 'application/json' },
    body: {
      model: JUDGE_MODEL,
      messages: [{
        role: 'user',
        content: [
          { type: 'text', text: `Image A is the original product photo of "${product}". Image B is an "enhanced" version. Judge whether B: (1) still clearly shows the same real product unchanged (no distortion, no missing/added parts, no melted logos/text), and (2) is equal or better quality than A (sharper/cleaner, not worse). Respond with strict JSON only: {"same_product": bool, "quality_ok": bool, "issue": "short string or null"}` },
          { type: 'text', text: 'Image A:' },
          { type: 'image_url', image_url: { url: originalDataUrl } },
          { type: 'text', text: 'Image B:' },
          { type: 'image_url', image_url: { url: editedDataUrl } }
        ]
      }]
    },
    json: true
  });
  const content = res.choices[0].message.content || '';
  const match = content.match(/\{[\s\S]*\}/);
  return match ? JSON.parse(match[0]) : { same_product: false, quality_ok: false, issue: 'unparseable judge response' };
}

async function enhanceOne(photo, productLabel) {
  const originalDataUrl = await toDataUrl.call(this, photo.image_url);
  let feedback = null;
  for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {
    let editedDataUrl;
    try { editedDataUrl = await editImage.call(this, originalDataUrl, productLabel, feedback); }
    catch (e) { return { ...photo, enhanced: false, enhanced_reason: 'edit_error: ' + e.message }; }
    if (!editedDataUrl) { feedback = 'no image returned, please return an edited image'; continue; }

    let verdict;
    try { verdict = await judgeImage.call(this, originalDataUrl, editedDataUrl, productLabel); }
    catch (e) { return { ...photo, enhanced: false, enhanced_reason: 'judge_error: ' + e.message }; }

    if (verdict.same_product && verdict.quality_ok) {
      return { ...photo, enhanced: true, enhanced_image_base64: editedDataUrl, enhance_attempts: attempt };
    }
    feedback = verdict.issue || 'quality or fidelity check failed';
  }
  return { ...photo, enhanced: false, enhanced_reason: feedback || 'exhausted attempts' };
}

const productLabel = `${item.brand || ''} ${item.product_name || ''}`.trim();
const photos = (item.photos || []).slice(0, 3);

const enhancedPhotos = [];
for (const photo of photos) {
  const result = await enhanceOne.call(this, photo, productLabel);
  enhancedPhotos.push(result);
}

return [{
  json: {
    ...item,
    enhanced_photos: enhancedPhotos
  }
}];
